static inline u64 btrfs_calc_trans_metadata_size(struct btrfs_root *root, /* <=== btrfs_calc_trans_metadata_size */ 
						 unsigned num_items)
{
	return (root->nodesize + root->nodesize * (BTRFS_MAX_LEVEL - 1)) *
		2 * num_items;
}

static inline u32 btrfs_file_extent_inline_item_len(struct extent_buffer *eb, /* <=== btrfs_file_extent_inline_item_len */ 
						    struct btrfs_item *e)
